toolScript:
const input = document.getElementById('input-text');
        const output = document.getElementById('output-text');
        // Comprehensive Stopwords List (English)
        const stopwords = new Set(["a", "about", "above", "after", "again", "against", "all", "am", "an", "and", "any", "are", "aren't", "as", "at", "be", "because", "been", "before", "being", "below", "between", "both", "but", "by", "can't", "cannot", "could", "couldn't", "did", "didn't", "do", "does", "doesn't", "doing", "don't", "down", "during", "each", "few", "for", "from", "further", "had", "hadn't", "has", "hasn't", "have", "haven't", "having", "he", "he'd", "he'll", "he's", "her", "here", "here's", "hers", "herself", "him", "himself", "his", "how", "how's", "i", "i'd", "i'll", "i'm", "i've", "if", "in", "into", "is", "isn't", "it", "it's", "its", "itself", "let's", "me", "more", "most", "mustn't", "my", "myself", "no", "nor", "not", "of", "off", "on", "once", "only", "or", "other", "ought", "our", "ours", "ourselves", "out", "over", "own", "same", "shan't", "she", "she'd", "she'll", "she's", "should", "shouldn't", "so", "some", "such", "than", "that", "that's", "the", "their", "theirs", "them", "themselves", "then", "there", "there's", "these", "they", "they'd", "they'll", "they're", "they've", "this", "those", "through", "to", "too", "under", "until", "up", "very", "was", "wasn't", "we", "we'd", "we'll", "we're", "we've", "were", "weren't", "what", "what's", "when", "when's", "where", "where's", "which", "while", "who", "who's", "whom", "why", "why's", "with", "won't", "would", "wouldn't", "you", "you'd", "you'll", "you're", "you've", "your", "yours", "yourself", "yourselves"]);
        function compress() {
            const text = input.value;
            const mode = document.getElementById('mode').value;
            let compressed = "";
            if (mode === 'stopwords') {
                compressed = text.split(/\b/).map(word => {
                    const lower = word.toLowerCase().trim();
                    if (stopwords.has(lower)) return " ";
                    return word;
                }).join("").replace(/\s+/g, ' ').trim();
            }
            else if (mode === 'minification') {
                compressed = text.replace(/\s+/g, ' ').trim();
                compressed = compressed.replace(/\s*([{}:,;])\s*/g, '$1');
            }
            else if (mode === 'aggressive') {
                compressed = text.toLowerCase()
                    .replace(/[^\w\s]/g, '')
                    .split(/\s+/)
                    .filter(w => !stopwords.has(w) && w.length > 2)
                    .join(" ");
            }
            output.value = compressed;
            updateStats();
        }
        function updateStats() {
            const textOrig = input.value;
            const textComp = output.value;
            // Human-Understandable Token Heuristic Implementation:
            // "In the world of LLMs, 1 token is roughly equal to 4 characters of text. 
            // To estimate your token count, we take the length of your text and divide it by 4."
            const tokensOrig = Math.ceil(textOrig.length / 4);
            const tokensComp = Math.ceil(textComp.length / 4);
            document.getElementById('stats-orig').innerText = `${tokensOrig.toLocaleString()} Tokens`;
            document.getElementById('stats-comp').innerText = `${tokensComp.toLocaleString()} Tokens`;
            // Recovery Math:
            // "To find your financial recovery, take the total number of tokens saved, 
            // divide that number by 1,000, and multiply by the price per 1k tokens."
            const tokenDelta = Math.max(0, tokensOrig - tokensComp);
            const pct = tokensOrig > 0 ? Math.round((tokenDelta / tokensOrig) * 100) : 0;
            const costPer1k = parseFloat(document.getElementById('model-cost').value);
            const savedCost = (tokenDelta / 1000) * costPer1k;
            document.getElementById('savings-pct').innerText = pct + "%";
            document.getElementById('savings-usd').innerText = '$' + savedCost.toFixed(4);
        }
        function copyOutput() {
            if (!output.value) return;
            output.select();
            document.execCommand('copy');
            // Visual feedback
            const btn = event.currentTarget;
            const original = btn.innerHTML;
            btn.innerHTML = "Tokens Copied!";
            btn.classList.replace('bg-slate-900', 'bg-teal-600');
            setTimeout(() => {
                btn.innerHTML = original;
                btn.classList.replace('bg-teal-600', 'bg-slate-900');
            }, 2000);
        }
        // Initialize Scroll Logic
        input.addEventListener('input', compress);
        // Initial Demo
        document.addEventListener('DOMContentLoaded', () => {
            input.value = "Welcome to the Context Squeezer. Large Language Models like ChatGPT process text in units called tokens. In a standard sentence, about 30% of the words are fluff. By removing them, we can fit more information into the window and save money on API costs.";
            compress();
        });
